create function pg_temp.assert_a(ok boolean)returns void language plpgsql as $$begin if ok is not true then raise exception 'automation_assertion';end if;end$$;
create function pg_temp.deny_a(q text,c text)returns void language plpgsql as $$begin begin execute q;exception when others then if sqlstate=c then return;end if;raise;end;raise exception 'expected_automation_denial';end$$;
create temp table auto_fixture(id uuid,customer uuid);grant all on auto_fixture to authenticated;
set local role authenticated;
select set_config('request.jwt.claim.sub','81000000-0000-4000-8000-000000000001',true);
do $$declare w uuid:='82000000-0000-4000-8000-000000000001';i jsonb;r jsonb;id uuid;begin
 i:=jsonb_build_object('command_id',gen_random_uuid(),'name','Synthetic automation','trigger_id','customer.created','condition',jsonb_build_object('account_kind',null),'action',jsonb_build_object('action_id','task.create','recipient_user_id','81000000-0000-4000-8000-000000000002'));
 r:=public.automation_v1_create(w,i);id:=(r->>'id')::uuid;perform pg_temp.assert_a(r=public.automation_v1_create(w,i));insert into auto_fixture(id)values(id);
 perform public.automation_v1_update(w,i||jsonb_build_object('command_id',gen_random_uuid(),'id',id,'expected_version',1,'name','Synthetic edited automation'));
 perform public.automation_v1_enable(w,jsonb_build_object('command_id',gen_random_uuid(),'id',id,'expected_version',2));
 perform pg_temp.assert_a(public.automation_v1_get(w,jsonb_build_object('id',id))->'record'->>'enabled'='true');
 perform pg_temp.assert_a(public.automation_v1_list(w,'{"limit":1}')->'items'->0->>'id'=id::text);
 r:=public.product_v1_customer_create(w,jsonb_build_object('command_id',gen_random_uuid(),'account_kind','legal_entity','legal_name','Synthetic action source'));update auto_fixture set customer=(r->>'id')::uuid;
 i:=jsonb_build_object('command_id',gen_random_uuid());r:=public.automation_v1_process_pending(w,i);perform pg_temp.assert_a(r->>'succeeded'='1'and r->>'failed'='0'and r=public.automation_v1_process_pending(w,i));
 perform pg_temp.assert_a(public.automation_v1_run_history(w,jsonb_build_object('id',id,'limit',1))->'items'->0->>'status'='succeeded');
 perform pg_temp.assert_a(public.automation_v1_process_pending(w,jsonb_build_object('command_id',gen_random_uuid()))->>'processed'='0');
 perform public.automation_v1_disable(w,jsonb_build_object('command_id',gen_random_uuid(),'id',id,'expected_version',3));
 perform pg_temp.deny_a(format('select public.automation_v1_create(%L,%L)',w,(i||jsonb_build_object('name','Invalid','trigger_id','customer.created','condition',jsonb_build_object('sql','select 1'),'action',jsonb_build_object('action_id','task.create','recipient_user_id','81000000-0000-4000-8000-000000000002')))::text),'22023');
end$$;
reset role;
select pg_temp.assert_a((select count(*)=1 from public.tasks where customer_id=(select customer from auto_fixture)));
select pg_temp.assert_a((select count(*)=1 from public.internal_automation_runs));
create function pg_temp.auto_audit_failure()returns trigger language plpgsql as $$begin raise exception 'automation_cutpoint';end$$;
create trigger auto_test_audit before insert on public.product_audit_events for each row execute function pg_temp.auto_audit_failure();
set local role authenticated;
select pg_temp.deny_a(format('select public.automation_v1_enable(%L,%L)','82000000-0000-4000-8000-000000000001',jsonb_build_object('command_id',gen_random_uuid(),'id',(select id from auto_fixture),'expected_version',4)::text),'P0001');
reset role;
select pg_temp.assert_a((select version=4 and not enabled from public.internal_automations));
drop trigger auto_test_audit on public.product_audit_events;
